//! TRUST runtime support layer: Rust code generated by the translator
//! depends on this crate at runtime.
//!
//! Design principles: user-visible values stay typst-library's `Value` (no
//! private value model); every semantic helper mirrors the corresponding
//! `typst-eval` interpretation (error messages and span behavior included).

use comemo::{Track, Tracked, TrackedMut};
use typst::Library;
use typst::World;
use typst::diag::{At, SourceResult, bail};
use typst::engine::{Engine, Route, Sink, Traced};
use typst::foundations::{
    Arg, Args, Array, Binding, Capturer, Closure, ClosureNode, Content, Context, Func,
    IntoValue, Module, Scope, Scopes, Selector, Str, Transformation, Value, ops,
};
use typst::introspection::{EmptyIntrospector, Introspector};
use typst::utils::{LazyHash, Protected};
use typst::syntax::ast::{self, AstNode};
use typst::syntax::{Span, Spanned, SyntaxKind};

use ecow::{EcoString, EcoVec, eco_format, eco_vec};
use typst::diag::{Hint, SourceDiagnostic, Trace};

/// **Self-contained materialization** of generated spans: replaces the
/// translator process's FileId number with the running process's own,
/// keeping the in-file position number (low 48 bits, deterministic for the
/// same text) as is.
///
/// Background: the generated `S{n}` constants bake in the absolute
/// numbering of the translator process's interner — a span's high 16 bits
/// are the FileId number and its low 48 bits the position (the
/// FileId/position split is `Span`'s public documented convention), and a
/// FileId number is only meaningful within the process that created it.
/// This function interns the path in the current process on **first use**
/// (`intern` is idempotent for the same path) and swaps in the current
/// process's number, so the host no longer needs a "pre-intern with the
/// same ordering" convention. Layout drift is self-checked via `id()`
/// equality.
pub fn source_span(path: &str, orig_raw: u64) -> Span {
    /// Mask for the low 48 bits (position number); the file number sits in
    /// the high bits (public documented convention:
    /// | 16 bits file id | 48 bits number |).
    const NUMBER_MASK: u64 = (1 << 48) - 1;
    if path.is_empty() {
        return Span::detached();
    }
    // Recursive-dependency form: an `@ns/name:ver/in-package-path` prefix
    // resolves to the Package root (same origin as the FileId the host
    // would create when loading the real package; after intern dedup the
    // span points straight at the host's package file, and plugin
    // relative-path resolution also anchors at the package root).
    let id = if path.starts_with('@') {
        let colon = path.find(':').expect("spec contains a version separator");
        let slash = path[colon..].find('/').expect("spec is followed by a path") + colon;
        let spec: typst::syntax::package::PackageSpec = path[..slash]
            .parse()
            .unwrap_or_else(|e| panic!("invalid spec {}: {e}", &path[..slash]));
        typst::syntax::RootedPath::new(
            typst::syntax::VirtualRoot::Package(spec),
            typst::syntax::VirtualPath::new(&path[slash + 1..])
                .unwrap_or_else(|_| panic!("invalid path {path}")),
        )
        .intern()
    } else {
        typst::syntax::RootedPath::new(
            typst::syntax::VirtualRoot::Project,
            typst::syntax::VirtualPath::new(path)
                .unwrap_or_else(|_| panic!("invalid path {path}")),
        )
        .intern()
    };
    let file_num = id.into_raw().get() as u64;
    let number = orig_raw & NUMBER_MASK;
    let raw = std::num::NonZeroU64::new((file_num << 48) | number)
        .expect("file id combined with position number is nonzero");
    let span = Span::from_raw(raw);
    assert_eq!(
        span.id(),
        Some(id),
        "span layout does not match typst's public documentation (version drift?); refusing to silently misalign"
    );
    span
}

// --- Host integration protocol (self-contained; the host does not need trust-world) ---

/// Function shape of the generated `module_init` (the module-assembly entry
/// evaluated once per build).
pub type ModuleInit = fn(&mut Engine, Tracked<Context>) -> SourceResult<Module>;

/// Driver shell for `module_init` (mirrors `typst_eval::eval`'s module
/// evaluation cache): builds an Engine (EmptyIntrospector + fresh Sink +
/// Route) plus `Context::none`; comemo memoizes on (world read constraints,
/// library contents, init fn), invalidates automatically when dependencies
/// change, and re-evaluates after eviction (`rt::fill` is idempotent for the
/// same value, so re-entry is safe). Only requires the host World to serve
/// external package files and Project-root data files (wasm plugins).
#[comemo::memoize]
pub fn init_module(
    world: Tracked<'_, dyn World + '_>,
    library: &LazyHash<Library>,
    init: ModuleInit,
) -> SourceResult<Module> {
    let mut sink = Sink::new();
    let traced = Traced::default();
    let mut engine = Engine {
        library,
        world,
        introspector: Protected::new(EmptyIntrospector.track()),
        traced: traced.track(),
        sink: sink.track_mut(),
        route: Route::default(),
    };
    let context = Context::none();
    init(&mut engine, context.track())
}

/// Injects a module into library.global (bind, not define, so same-named
/// definitions may be replaced) + **rebuilds the std binding** (std holds
/// another Arc copy of global; scope copy-on-write would fork the two) +
/// rewraps the `LazyHash` (visible to comemo's cache hashing). Returns the
/// new library for the host to swap into its world.
pub fn bind_module(
    library: &LazyHash<Library>,
    name: &'static str,
    module: Module,
) -> LazyHash<Library> {
    let mut library: Library = (**library).clone();
    library
        .global
        .scope_mut()
        .bind(name.into(), Binding::detached(module));
    library.std = Binding::detached(library.global.clone().into_value());
    install_stub_fast_path(&mut library);
    typst::utils::LazyHash::new(library)
}

/// `Routines.eval_closure` dispatch with a stub direct call. When the
/// closure is one of our stubs (captured scope carries `__trust_routine`),
/// it goes through [`eval_stub_native`] — **comemo accounting is kept**
/// (the memo key is isomorphic to typst-eval's `eval_closure`: same types,
/// same order, same dedup granularity); only "interpreting the stub body"
/// is replaced by a direct call into the native body. Dropping memoization
/// entirely (a bare direct call) would also lose comemo's parallel
/// deduplication (concurrent identical calls would each re-execute) and
/// drops cold-compile throughput to 0.43× — the accounting is load-bearing,
/// not overhead. Non-stub closures fall through unchanged to typst-eval's
/// default routine.
pub fn trust_eval_closure(
    func: &Func,
    closure: &LazyHash<Closure>,
    world: Tracked<'_, dyn World + '_>,
    library: &LazyHash<Library>,
    introspector: Tracked<'_, dyn Introspector + '_>,
    traced: Tracked<'_, Traced>,
    sink: TrackedMut<'_, Sink>,
    route: Tracked<'_, Route<'_>>,
    context: Tracked<'_, Context>,
    args: Args,
) -> SourceResult<Value> {
    if stub_routine(closure).is_some() {
        return eval_stub_native(
            func, closure, world, library, introspector, traced, sink, route, context, args,
        );
    }
    typst_eval::eval_closure(
        func,
        closure,
        world,
        library,
        introspector,
        traced,
        sink,
        route,
        context,
        args,
    )
}

/// Fetches the direct-call routine from a stub's captured scope (the hit
/// test; non-stub closures pay a single scope lookup). **Borrows
/// throughout** — cloning the TrustRoutine (with its defaults Vec) would be
/// pure overhead on the hot path: the check only needs a reference, and so
/// does the direct-call body (the state handle is cloned once as an Arc
/// only when inserting the argument, as the protocol requires).
fn stub_routine(closure: &LazyHash<Closure>) -> Option<(&TrustRoutine, Option<&StateSlot>)> {
    let routine = closure.captured.get("__trust_routine")?;
    let state = closure.captured.get("__trust_state");
    let Value::Dyn(routine) = routine.read() else {
        return None;
    };
    let cell = routine.downcast::<TrustRoutine>()?;
    let slot = match state {
        Some(state) => {
            let Value::Dyn(state) = state.read() else {
                return None;
            };
            Some(state.downcast::<StateSlot>()?)
        }
        None => None,
    };
    Some((cell, slot))
}

/// Memoized stub direct-call body (input set identical to typst-eval's
/// `eval_closure`, so the comemo key is isomorphic — same types, same
/// order; internally performs default injection + state-handle insertion +
/// the native body call in one step, skipping the stub body's
/// interpretation and inner dispatch).
#[comemo::memoize]
fn eval_stub_native(
    func: &Func,
    closure: &LazyHash<Closure>,
    world: Tracked<'_, dyn World + '_>,
    library: &LazyHash<Library>,
    introspector: Tracked<'_, dyn Introspector + '_>,
    traced: Tracked<'_, Traced>,
    sink: TrackedMut<'_, Sink>,
    route: Tracked<'_, Route<'_>>,
    context: Tracked<'_, Context>,
    mut args: Args,
) -> SourceResult<Value> {
    let _ = func;
    let Some((cell, slot)) = stub_routine(closure) else {
        return Err(eco_vec![SourceDiagnostic::error(
            Span::detached(),
            Str::from("stub direct call missing routine marker (generator bug)"),
        )]);
    };
    let mut engine = Engine {
        library,
        world,
        introspector: Protected::from_raw(introspector),
        traced,
        sink,
        route: Route::extend(route),
    };
    // Named-argument default injection (mirrors eval_closure's
    // default.clone() at binding time): only fills in items the caller did
    // not provide, and inserts them **before** the caller's arguments —
    // `Args::named`'s "last one wins for the same name" semantics keeps the
    // caller's value in effect. Positional binding (eat skips named items)
    // is unaffected by the insertion position.
    for (name, value) in &cell.defaults {
        if !args
            .items
            .iter()
            .any(|arg| arg.name.as_deref() == Some(name.as_str()))
        {
            args.items.insert(
                0,
                Arg {
                    span: args.span,
                    name: Some(name.clone()),
                    value: Spanned::new(value.clone(), args.span),
                },
            );
        }
    }
    if let Some(slot) = slot {
        args.insert(0, args.span, Value::Dyn(typst::foundations::Dynamic::new(slot.clone())));
    }
    (cell.f)(&mut engine, context, &mut args)
}
/// Swaps `Library.routines.eval_closure` for [`trust_eval_closure`].
/// The routines table is a `&'static` shared reference and cannot be edited
/// in place (that would affect every other Library in the process —
/// including the comparison side): copy it, replace just that pointer, and
/// `Box::leak` it as this crate's static. `Routines`'s Hash is an empty
/// impl, so the swap does not affect the LazyHash key. Only replaces when
/// the current routine is typst-eval's default (a host's custom routine is
/// never overridden; repeated installs are idempotent).
fn install_stub_fast_path(library: &mut Library) {
    static FAST: std::sync::OnceLock<&'static typst::routines::Routines> =
        std::sync::OnceLock::new();
    let current = library.routines;
    if std::ptr::eq(
        current.eval_closure as *const (),
        trust_eval_closure as *const (),
    ) {
        return; // already installed (repeated install)
    }
    if !std::ptr::eq(
        current.eval_closure as *const (),
        typst_eval::eval_closure as *const (),
    ) {
        return; // host-defined routine: respect it, don't override
    }
    let fast = FAST.get_or_init(|| {
        Box::leak(Box::new(typst::routines::Routines {
            eval_closure: trust_eval_closure,
            ..*current
        }))
    });
    library.routines = fast;
}

/// Storage and slot primitives for per-build state (the per-build slot
/// scheme).
///
/// The typst runtime model is: a finite set of named slots + one write per
/// evaluation + snapshots by value; this module provides the matching Rust
/// shapes — write-once cells (`OnceLock<Value>`) and a state handle that
/// travels with the function value ([`StateSlot`], the native-closure stub
/// approach): each evaluation of `module_init` constructs fresh instances,
/// there is no global registry, and the lifetime follows the function value
/// (mirroring the data layout of typst closures).
fn state_error(message: &str) -> EcoVec<SourceDiagnostic> {
    eco_vec![SourceDiagnostic::error(
        Span::detached(),
        typst::foundations::Str::from(message),
    )]
}

// --- Single gate for slot access (mirrors Binding::read / Binding::write) ---
//
// Write-once slots (OnceLock) and mutable slots (Mutex) share the same
// `read`/`fill` entries: the translation side does not need to (and cannot,
// at every emission site) dispatch on the field type — a slot's mutability
// is decided at plan time via mutable_slots, which picks the field type;
// the behavioral differences are gathered into these two entries.

/// Uniform access to slot fields (OnceLock writes once; Mutex writes any
/// number of times).
pub trait SlotField {
    fn slot_read(&self) -> SourceResult<Value>;
    fn slot_fill(&self, value: Value) -> SourceResult<()>;
}

/// Reads a top-level binding slot (write-once cell).
fn read_lock(slot: &std::sync::OnceLock<Value>) -> SourceResult<Value> {
        if let Some(v) = slot.get() {
            if std::env::var_os("TRUST_TRACE_SLOTS").is_some() {
                eprintln!("[slot] read-ok  @{:?}", std::ptr::from_ref(slot));
            }
            return Ok(v.clone());
        }
        if std::env::var_os("TRUST_SLOT_PANIC").is_some() {
            panic!("slot-unfilled @{:?}", std::ptr::from_ref(slot));
        }
        Err(state_error(&format!(
            "module slot not initialized (evaluation-order error, slot @{:?})",
            std::ptr::from_ref(slot)
        )))
    }

/// Fills a top-level binding slot (write-once). The first successful fill
/// wins; on re-entry (e.g. `module_init` re-evaluated after a module-cache
/// eviction) the same value is an idempotent no-op, while a different value
/// is still a generator bug and is reported as an error.
fn fill_lock(slot: &std::sync::OnceLock<Value>, value: Value) -> SourceResult<()> {
    if std::env::var_os("TRUST_TRACE_SLOTS").is_some() {
        eprintln!("[slot] fill    @{:?}", std::ptr::from_ref(slot));
    }
    match slot.get() {
        Some(existing) => {
            if *existing == value {
                Ok(())
            } else {
                Err(state_error("module slot refilled with a different value (generator bug)"))
            }
        }
        None => slot
            .set(value)
            .map_err(|_| state_error("concurrent conflicting fill of module slot")),
    }
}

impl SlotField for std::sync::OnceLock<Value> {
    fn slot_read(&self) -> SourceResult<Value> {
        read_lock(self)
    }
    fn slot_fill(&self, value: Value) -> SourceResult<()> {
        fill_lock(self, value)
    }
}

impl SlotField for std::sync::Mutex<Value> {
    fn slot_read(&self) -> SourceResult<Value> {
        read_ms(self)
    }
    fn slot_fill(&self, value: Value) -> SourceResult<()> {
        fill_ms(self, value)
    }
}

/// Reads a top-level binding slot (single gate: the field type decides
/// write-once vs mutable semantics).
pub fn read(slot: &impl SlotField) -> SourceResult<Value> {
    slot.slot_read()
}

/// Fills a top-level binding slot (single gate).
pub fn fill(slot: &impl SlotField, value: Value) -> SourceResult<()> {
    slot.slot_fill(value)
}

/// Reads a global-name slot materialized at creation time: with a value,
/// reads the slot (mirroring typst's creation-time capture); without one,
/// falls back to a call-time global lookup (mirroring call-time resolution
/// of names not visible at creation time).
pub fn read_or(
    slot: &std::sync::OnceLock<Value>,
    engine: &mut Engine,
    name: &str,
) -> SourceResult<Value> {
    match slot.get() {
        Some(value) => Ok(value.clone()),
        None => global(engine, name, Span::detached()),
    }
}

/// Reads a slot whose value is stored as content (the body).
pub fn read_content(slot: &std::sync::OnceLock<Value>) -> SourceResult<Content> {
    match read_lock(slot)? {
        Value::Content(content) => Ok(content),
        _ => Err(state_error("module body slot does not hold content (generator bug)")),
    }
}

/// Resolves a name in the standard library's global scope (mirrors the
/// interpreter's `Scopes::get`, **by direct reuse**: beyond locals it looks
/// up `library.global`, with a special case for the name `std` on miss; the
/// unknown-variable error on miss carries the minus hint — message and hint
/// are generated by typst itself, zero drift).
pub fn global(engine: &mut Engine, name: &str, span: Span) -> SourceResult<Value> {
    let library: &Library = engine.library;
    let scopes = Scopes::new(Some(library));
    let binding = scopes.get(name).at(span)?;
    Ok(binding.read_checked((engine, span)).clone())
}

/// Creation-time materialization lookup for **code-name captures** (mirrors
/// CapturesVisitor's `Ident → capture(Scopes::get)`): resolves through
/// `Scopes::get`; a miss returns None (at call time the name is resolved by
/// the bindings inside the closure body itself).
pub fn capture_code_opt(engine: &mut Engine, name: &str) -> SourceResult<Option<Value>> {
    let library: &Library = engine.library;
    let scopes = Scopes::new(Some(library));
    Ok(scopes
        .get(name)
        .ok()
        .map(|b| b.read_checked((engine, Span::detached())).clone()))
}

/// Creation-time materialization lookup for **math-name captures** (mirrors
/// CapturesVisitor's `MathIdent → capture(Scopes::get_in_math)`): looks up
/// only the math scope (plus the local chain) — **global-only names are not
/// part of the capture surface** (as in typst issue-2885: `$rgb$` must error
/// with "unknown variable: rgb" rather than resolve to the global function).
pub fn capture_math_opt(engine: &mut Engine, name: &str) -> SourceResult<Option<Value>> {
    let library: &Library = engine.library;
    let scopes = Scopes::new(Some(library));
    Ok(scopes
        .get_in_math(name)
        .ok()
        .map(|b| b.read_checked((engine, Span::detached())).clone()))
}

/// Global lookup (code name) returning `None` when absent (mirrors typst
/// capture semantics: names not visible at creation time are not captured;
/// they are bound at call time by the closure body's own imports).
pub fn global_opt(engine: &mut Engine, name: &str) -> SourceResult<Option<Value>> {
    capture_code_opt(engine, name)
}

/// Field access `target.name` (mirrors `access_field`: `Value::field` plus
/// a get-rule style-chain fallback — a field of an element function (e.g.
/// `text.size`) that misses the static field is read from the context's
/// style chain; the sink passes the engine through so deprecation warnings
/// can be emitted).
pub fn field(
    target: &Value,
    name: &str,
    engine: &mut Engine,
    context: Tracked<Context>,
    span: Span,
) -> SourceResult<Value> {
    let err = match target.field(name, (engine, span)).at(span) {
        Ok(value) => return Ok(value),
        Err(err) => err,
    };
    // Check whether this is a get rule field access (mirrors access_field:
    // the styles check is deferred until it is confirmed to be a style-chain
    // field).
    if let Value::Func(func) = target
        && let Some(element) = func.to_element()
        && let Some(id) = element.field_id(name)
    {
        let styles = context.styles();
        let chain = styles.as_ref().map(|&s| s).unwrap_or_default();
        if let Ok(value) = element.field_from_styles(id, chain) {
            let _ = styles.at(span)?;
            return Ok(value);
        }
    }
    Err(err)
}

/// Call-site guardrail: function call depth (mirrors
/// `vm.engine.route.check_call_depth`; mutual recursion produces an error
/// instead of a segfault).
pub fn check_call_depth(engine: &Engine, span: Span) -> SourceResult<()> {
    engine.route.check_call_depth().at(span)
}

/// Resolves the callee (mirrors native `callee.eval()?.cast::<Func>()`:
/// function values, type values (their constructors), and symbols (their
/// associated functions) are all callable; everything else errors with the
/// cast message — arguments are not evaluated before this point, matching
/// the native evaluation order). Takes the value by value (the call site
/// holds a temporary; the common path clones nothing).
pub fn callee(value: Value, span: Span) -> SourceResult<Func> {
    if let Value::Func(func) = value {
        return Ok(func);
    }
    value.cast::<Func>().at(span)
}

/// Unified call path (mirrors `call_func`): the func is tagged with the
/// call-site span and errors carry a tracepoint (`error occurred in this
/// call of function ...`); method calls pass the target as the first
/// positional argument via `insert` (mirrors
/// `args.insert(0, target_expr.span(), target)`).
pub fn call_with(
    func: Func,
    insert: Option<(Value, Span)>,
    span: Span,
    mut args: Args,
    engine: &mut Engine,
    context: Tracked<Context>,
) -> SourceResult<Value> {
    let func = func.spanned(span);
    if let Some((target, target_span)) = insert {
        args.insert(0, target_span, target);
    }
    // The tracepoint name is materialized only on the error path (the trace
    // closure is called lazily). No stacker::maybe_grow: call depth is cut
    // off by the check_call_depth guardrail (80 levels) before stack
    // overflow can happen; a per-call stack probe would be pure overhead
    // (the native interpreter path needs it, the compiled path does not).
    func.call(engine, context, args).trace(
        engine.world,
        || typst::diag::Tracepoint::Call(func.name().map(EcoString::from)),
        span,
    )
}

/// Callee resolution for method calls (mirrors `eval_field_callee`: methods
/// on the type's scope first, then the content element's scope;
/// Symbol/Func/Type/Module allow field-call syntax; errors use the original
/// two-stage form + hint set).
///
/// Returns `(function value, target value when it is a method call)`; for a
/// method call the caller must pass the target as the first positional
/// argument (the target is returned by value, saving a clone).
pub fn method_callee(
    target: Value,
    name: &str,
    access_text: &str,
    engine: &mut Engine,
    span: Span,
) -> SourceResult<(Func, Option<Value>)> {
    let sink = (&mut *engine, span);
    let mut is_method_call = false;
    let callee_value = if let Some(method) = target.ty().scope().get(name) {
        is_method_call = true;
        method.read_checked(sink).clone()
    } else if let Value::Content(content) = &target
        && let Some(method) = content.elem().scope().get(name)
    {
        is_method_call = true;
        method.read_checked(sink).clone()
    } else if matches!(
        &target,
        Value::Symbol(_) | Value::Func(_) | Value::Type(_) | Value::Module(_)
    ) {
        target.field(name, sink).at(span)?
    } else {
        // Otherwise we cannot call this field and produce an error.
        match target.field(name, sink) {
            Ok(callee_value) => {
                let is_dict = matches!(target, Value::Dict(_));
                let is_named = matches!(target, Value::Args(_));
                let (kind, ty_name) = element_or_type_with_name(&target);
                let message = if is_dict {
                    EcoString::from("cannot directly call dictionary keys as functions")
                } else if is_named {
                    EcoString::from("cannot directly call named argument fields as functions")
                } else {
                    eco_format!("`{name}` is not a valid method for {kind} `{ty_name}`")
                };
                let mut err =
                    SourceDiagnostic::error(span, typst::foundations::Str::from(message));
                if callee_value.clone().cast::<Func>().is_ok() {
                    err = err.with_hint(eco_format!(
                        "to call the stored function, wrap the field access in parentheses: `({access_text})(..)`"
                    ));
                } else {
                    err = err.with_hint(eco_format!(
                        "to access the `{name}` {}, remove the function arguments: `{access_text}`",
                        if is_dict { "key" } else if is_named { "argument" } else { "field" },
                    ));
                }
                if is_dict {
                    err = err.with_hint(
                        "dictionary keys cannot be used with method syntax as keys \
                         could conflict with built-in method names",
                    );
                } else if is_named {
                    err = err.with_hint(
                        "named arguments cannot be used with method syntax as argument \
                         names could conflict with built-in method names",
                    );
                }
                return Err(eco_vec![err]);
            }
            Err(_) => {
                let (kind, ty_name) = element_or_type_with_name(&target);
                bail!(span, "{kind} {ty_name} has no method `{name}`")
            }
        }
    };
    match callee_value {
        Value::Func(func) if is_method_call => Ok((func, Some(target))),
        Value::Func(func) => Ok((func, None)),
        callee_value => callee_value
            .cast::<Func>()
            .map(|func| (func, None))
            .at(span),
    }
}

/// If the value is content, the string "element" and the name of its element
/// function, or the string "type" and the long name of the value's type.
fn element_or_type_with_name(value: &Value) -> (&'static str, EcoString) {
    if let Value::Content(content) = value {
        ("element", EcoString::from(content.elem().name()))
    } else {
        ("type", EcoString::from(value.ty().long_name()))
    }
}

/// Builds a closure value from a source snippet: the node is parsed by the
/// official parser, defaults are passed in after the generated code
/// evaluates them at creation time, and captured carries the current values
/// of the outer bindings.
///
/// The closure body is interpreted by typst-eval — the fidelity path for
/// v1; closure parameter defaults are evaluated the same number of times as
/// in the original (at creation time).
/// Registry of virtual sources for interpreted closures: FileId → snippet
/// source (for diagnostic locations; the host looks it up via
/// [`closure_source`] when printing errors).
static CLOSURE_SOURCES: std::sync::RwLock<Vec<(typst::syntax::FileId, String)>> =
    std::sync::RwLock::new(Vec::new());

/// Looks up the source of a virtual closure file (`None` if absent).
pub fn closure_source(id: typst::syntax::FileId) -> Option<String> {
    CLOSURE_SOURCES
        .read()
        .unwrap()
        .iter()
        .find(|(fid, _)| *fid == id)
        .map(|(_, src)| src.clone())
}

/// One-shot parse of an interpreted snippet (`closure`/`native_closure`),
/// **without a global cache**: meant as the initializer of a per-call-site
/// `static LazyLock` in generated code — the static itself is the cache, so
/// the hot path takes no lock and does no lookup. Mirrors native closure
/// creation — `Eval for ast::Closure`'s node is a reference into the source
/// file's AST (an Arc inside SyntaxNode), with zero parse and zero lookup
/// at creation time; here the snippet is located once (parse + find the
/// Closure node) and later creations just clone the node reference — the
/// same "locate the AST once, rebuild values cheaply" shape as native. The
/// snippet is also registered in [`CLOSURE_SOURCES`] (diagnostic lookup,
/// cold path; the virtual file lets spans resolve to snippet lines).
pub fn parse_closure_node(src: &str) -> (typst_syntax::SyntaxNode, usize) {
    let trimmed = src.trim_start();
    let text = if trimmed.starts_with("let ") {
        format!("#{trimmed}")
    } else {
        format!("#let __trust_closure = ({trimmed})")
    };
    let n = CLOSURE_SOURCES.read().unwrap().len();
    let id = typst::syntax::RootedPath::new(
        typst::syntax::VirtualRoot::Project,
        typst::syntax::VirtualPath::new(format!("__trust_closure_{n}.typ"))
            .expect("valid closure path"),
    )
    .intern();
    let source = typst::syntax::Source::new(id, text.clone());
    CLOSURE_SOURCES.write().unwrap().push((id, text.clone()));
    let node = find_closure_node(source.root())
        .unwrap_or_else(|| panic!("closure source parses to a closure: {text:?}"))
        .clone();
    let num_pos_params = node
        .cast::<ast::Closure>()
        .expect("closure node casts")
        .params()
        .children()
        .filter(|p| matches!(p, ast::Param::Pos(_)))
        .count();
    (node, num_pos_params)
}

fn cached_closure_node(src: &str) -> (typst_syntax::SyntaxNode, usize) {
    static CACHE: std::sync::LazyLock<
        std::sync::RwLock<std::collections::HashMap<String, (typst_syntax::SyntaxNode, usize)>>,
    > = std::sync::LazyLock::new(|| std::sync::RwLock::new(std::collections::HashMap::new()));
    if let Some(hit) = CACHE.read().unwrap().get(src) {
        return hit.clone();
    }
    // Valid markup forms: a named binding embeds directly; anything else (a
    // bare closure / context body) is wrapped in parentheses — markup's
    // `#let x = expr` init ends **at the end of the line**, so a multi-line
    // bare closure body would be truncated to an empty body; the
    // parentheses force a code context that spans lines.
    let trimmed = src.trim_start();
    let text = if trimmed.starts_with("let ") {
        format!("#{trimmed}")
    } else {
        format!("#let __trust_closure = ({trimmed})")
    };
    let n = CLOSURE_SOURCES.read().unwrap().len();
    let id = typst::syntax::RootedPath::new(
        typst::syntax::VirtualRoot::Project,
        typst::syntax::VirtualPath::new(format!("__trust_closure_{n}.typ"))
            .expect("valid closure path"),
    )
    .intern();
    let source = typst::syntax::Source::new(id, text.clone());
    CLOSURE_SOURCES.write().unwrap().push((id, text.clone()));
    // The snippet may be a bare closure `(x) => ..` or a named binding
    // `f(x) = ..` (a LetBinding wrapping the Closure); take the first
    // Closure node either way. The named form keeps its name, so recursive
    // self-reference works.
    let node = find_closure_node(source.root())
        .unwrap_or_else(|| panic!("closure source parses to a closure: {text:?}"))
        .clone();
    let num_pos_params = node
        .cast::<ast::Closure>()
        .expect("closure node casts")
        .params()
        .children()
        .filter(|p| matches!(p, ast::Param::Pos(_)))
        .count();
    CACHE
        .write()
        .unwrap()
        .insert(src.to_string(), (node.clone(), num_pos_params));
    (node, num_pos_params)
}

/// Materializes not-yet-captured names at creation time: global scope
/// first, then the math scope (mirrors native closure creation —
/// CapturesVisitor resolves against the scopes at the creation point, where
/// both `get` and `get_in_math` carry the library base; an interpreted
/// snippet's captured scope has no base, which this restores), with the
/// `std` special case as in [`global_opt`]. A name still not found is
/// simply not captured (call time then reports unknown variable, same as
/// native).
fn resolve_pending(
    engine: &mut Engine,
    captured: &mut Vec<(&'static str, Value)>,
    pending: &[(&'static str, bool)],
) {
    for (name, in_math) in pending {
        if captured.iter().any(|(n, _)| n == name) {
            continue;
        }
        let found = if *in_math {
            capture_math_opt(engine, name)
        } else {
            capture_code_opt(engine, name)
        };
        if let Ok(Some(value)) = found {
            captured.push((name, value));
        }
    }
}

pub fn closure(
    src: &str,
    defaults: Vec<Value>,
    captured: &[(&'static str, Value)],
    pending: &[(&'static str, bool)],
    engine: &mut Engine,
) -> Func {
    let (node, num_pos_params) = cached_closure_node(src);
    let mut captured: Vec<(&'static str, Value)> = captured.to_vec();
    resolve_pending(engine, &mut captured, pending);
    // Probe the debug switch once (previously this ran getenv on **every
    // closure creation** — glibc's getenv also takes the environ lock, pure
    // overhead on the generated side's cold compiles).
    static DEBUG_CAPTURE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    let debug = *DEBUG_CAPTURE.get_or_init(|| std::env::var_os("TRUST_DEBUG_CAPTURE").is_some());
    let mut scope = Scope::new();
    for (name, value) in &captured {
        if debug && src.contains("ctx => {") {
            let brief = format!("{value:?}");
            eprintln!("[capture] {name} = {}", &brief[..brief.len().min(120)]);
        }
        // Captured bindings get the read-only mark (mirrors
        // `Binding::capture(Capturer::Function)` on typst closures'
        // captured scope): writes to captures are rejected by typst's
        // evaluator via `Binding::write` with its read-only error.
        scope.bind(
            (*name).into(),
            Binding::detached(value.clone()).capture(Capturer::Function),
        );
    }
    let closure_span = node.span();
    Func::from(Closure {
        node: ClosureNode::Closure(node),
        defaults,
        captured: scope,
        num_pos_params,
    })
    // Mirrors typst: the closure is spanned at creation (the definition
    // site); error propagation points inside the interpreted body (e.g. the
    // cast in array.any's predicate using test.span()) can now resolve to
    // the virtual source.
    .spanned(closure_span)
}

/// Finds the first Closure node in pre-order.
fn find_closure_node(node: &typst_syntax::SyntaxNode) -> Option<&typst_syntax::SyntaxNode> {
    if node.kind() == SyntaxKind::Closure {
        return Some(node);
    }
    node.children().find_map(find_closure_node)
}

/// Join semantics of code blocks (mirrors `ops::join`).
pub fn join(lhs: Value, rhs: Value, span: Span) -> SourceResult<Value> {
    ops::join(lhs, rhs).at(span)
}

/// Condition evaluation for if/while: non-boolean values error via the
/// original cast.
pub fn boolean(value: Value, span: Span) -> SourceResult<bool> {
    value.cast::<bool>().at(span)
}

/// Iteration guardrail limit for while loops (mirrors
/// `typst-eval/src/flow.rs`: `MAX_ITERATIONS = 10_000`, beyond which
/// "loop seems to be infinite" is reported).
pub const MAX_ITERATIONS: usize = 10_000;

/// Positional parameter binding (declaration order; mirrors eval_closure's
/// `args.expect`).
pub fn param_pos(args: &mut Args, name: &str, _span: Span) -> SourceResult<Value> {
    args.expect::<Value>(name)
}

/// Markup smart quotes (`'` / `"`): builds a smartquote element (the
/// open/close and language-dependent resolution semantics are left to
/// layout; mirrors eval_markup's SmartQuoteElem).
pub fn smartquote(double: bool) -> typst::foundations::Content {
    use typst::foundations::NativeElement;
    typst::text::SmartQuoteElem::new().with_double(double).pack()
}

/// Markup sequence folding (mirrors eval_markup's per-item dispatch): **a
/// label item attaches to the last attachable element in the sequence**
/// (`labelled`; a standalone label content item would be invisible to
/// queries); other values enter the sequence via display, and the result is
/// folded with Content::sequence at the end.
pub fn attach_labels(
    engine: &mut Engine,
    items: Vec<Value>,
) -> typst::foundations::Content {
    let mut seq: Vec<typst::foundations::Content> = Vec::with_capacity(items.len());
    for item in items {
        if let Value::Label(label) = item {
            // Mirrors eval_markup's two label-attachment warnings: already
            // labelled → "content labelled multiple times"; no attachable
            // element in the sequence → "label `x` is not attached to
            // anything" (warning spans may be the element's or detached;
            // only the message text is compared).
            if let Some(elem) = seq
                .iter_mut()
                .rev()
                .find(|n| !n.can::<dyn typst::foundations::Unlabellable>())
            {
                if elem.label().is_some() {
                    engine.sink.warn(typst::diag::warning!(
                        elem.span(),
                        "content labelled multiple times";
                        hint: "only the last label is used, the rest are ignored";
                    ));
                }
                *elem = std::mem::take(elem).labelled(label);
            } else {
                engine.sink.warn(typst::diag::warning!(
                    Span::detached(),
                    "label `{}` is not attached to anything",
                    format!("<{}>", label.resolve()),
                ));
            }
        } else {
            seq.push(item.display());
        }
    }
    typst::foundations::Content::sequence(seq)
}

/// `= body` (a level-depth heading): mirrors eval_markup's
/// `HeadingElem::new(body).with_depth(depth).pack()`.
pub fn heading(body: typst::foundations::Content, depth: usize) -> typst::foundations::Content {
    use typst::foundations::NativeElement;
    // ast::Heading::depth() is the equals-sign count (a NonZero ≥ 1); pass
    // it through.
    let depth = std::num::NonZeroUsize::new(depth.max(1)).expect("depth >= 1");
    typst::model::HeadingElem::new(body)
        .with_depth(depth)
        .pack()
}

/// `- body` list item: mirrors `ListItem::new(body).pack()` (consecutive
/// items are grouped into a List at realize time; no aggregation needed on
/// the translation side).
pub fn list_item(body: typst::foundations::Content) -> typst::foundations::Content {
    use typst::foundations::NativeElement;
    typst::model::ListItem::new(body).pack()
}

/// `+ body` enum item (`number` is the explicit index in the `+3.` form).
pub fn enum_item(
    body: typst::foundations::Content,
    number: Option<u64>,
) -> typst::foundations::Content {
    use typst::foundations::{NativeElement, Smart};
    let mut elem = typst::model::EnumItem::new(body);
    if let Some(n) = number {
        elem.number.set(Smart::Custom(n));
    }
    elem.pack()
}

/// `/ term: desc` term item.
pub fn term_item(
    term: typst::foundations::Content,
    description: typst::foundations::Content,
) -> typst::foundations::Content {
    use typst::foundations::NativeElement;
    typst::model::TermItem::new(term, description).pack()
}

/// Bare link in markup (`https://…`): mirrors `Url::new(...)` +
/// `LinkElem::from_url(url).pack()`.
pub fn link(url: &str, at: Span) -> SourceResult<typst::foundations::Content> {
    use typst::foundations::NativeElement;
    let url = typst::model::Url::new(url.to_string()).at(at)?;
    Ok(typst::model::LinkElem::from_url(url).pack())
}

/// `*body*`: mirrors eval_markup's `StrongElem::new(body).pack()`.
pub fn strong(body: typst::foundations::Content) -> typst::foundations::Content {
    use typst::foundations::NativeElement;
    typst::model::StrongElem::new(body).pack()
}

/// `_body_`: mirrors eval_markup's `EmphElem::new(body).pack()`.
pub fn emph(body: typst::foundations::Content) -> typst::foundations::Content {
    use typst::foundations::NativeElement;
    typst::model::EmphElem::new(body).pack()
}

/// Markup escapes/shorthands: mirrors the original
/// `Value::Symbol(runtime_char)` (note: **not** a text element — the two
/// have the same repr shape but different types, so equality tells them
/// apart; translating `[\[]` to text would make `== [\[]` always false).
/// The caller's display materializes it into a symbol element when it
/// enters a content sequence.
pub fn symbol_value(c: char) -> Value {
    Value::Symbol(typst::foundations::Symbol::runtime_char(c))
}

/// Code-position Raw: builds a RawElem from the line list + language +
/// block flag (mirrors typst-eval's `Eval for ast::Raw`; line spans are
/// detached — diagnostic-only, does not affect the value).
pub fn raw(lines: EcoVec<EcoString>, lang: Option<EcoString>, block: bool) -> Value {
    use typst::foundations::NativeElement;
    let lines: EcoVec<(EcoString, Span)> =
        lines.into_iter().map(|l| (l, Span::detached())).collect();
    let mut elem = typst::text::RawElem::new(typst::text::RawContent::Lines(lines))
        .with_block(block);
    if let Some(lang) = lang {
        elem.lang.set(Some(lang));
    }
    Value::Content(elem.pack())
}

/// Per-call-site static version of interpreted closure creation (the node
/// comes from the call site's static; the pending materialization protocol
/// is as in [`closure`]).
pub fn closure_node_at(
    node: &(typst_syntax::SyntaxNode, usize),
    defaults: Vec<Value>,
    captured: &[(&'static str, Value)],
    pending: &[(&'static str, bool)],
    engine: &mut Engine,
) -> Func {
    let (node, num_pos_params) = node.clone();
    let mut captured: Vec<(&'static str, Value)> = captured.to_vec();
    resolve_pending(engine, &mut captured, pending);
    let mut scope = Scope::new();
    for (name, value) in &captured {
        // Same as `closure`: captured bindings get the read-only mark.
        scope.bind(
            (*name).into(),
            Binding::detached(value.clone()).capture(Capturer::Function),
        );
    }
    let closure_span = node.span();
    Func::from(Closure {
        node: ClosureNode::Closure(node),
        defaults,
        captured: scope,
        num_pos_params,
    })
    .spanned(closure_span)
}

/// Self-function cache for self-recursive closures (the stub is rebuilt
/// once per **instance**): creation carries the defaults; on first
/// self-reference a signature-faithful stub is rebuilt with the same
/// StateSlot and cached — N levels of recursion rebuild it only once, and
/// its identity (the slot id) matches the original instance.
pub struct SelfFuncCell {
    defaults: Vec<Value>,
    func: std::sync::OnceLock<Func>,
}

pub fn self_func_cell(defaults: Vec<Value>) -> SelfFuncCell {
    SelfFuncCell {
        defaults,
        func: std::sync::OnceLock::new(),
    }
}

pub fn self_func(
    cell: &SelfFuncCell,
    data: &'static typst::foundations::NativeFuncData,
    params_src: &str,
    slot: &StateSlot,
) -> Func {
    cell.func
        .get_or_init(|| native_closure(data, params_src, cell.defaults.clone(), Some(slot)))
        .clone()
}

/// Static-node version (the node comes from the call site's static;
/// rebuilding takes no lookup and no lock).
pub fn self_func_node(
    cell: &SelfFuncCell,
    data: &'static typst::foundations::NativeFuncData,
    node: &(typst_syntax::SyntaxNode, usize),
    slot: &StateSlot,
) -> Func {
    cell.func
        .get_or_init(|| native_closure_node(data, node, cell.defaults.clone(), Some(slot)))
        .clone()
}

/// Unpacking with the slot (for self-recursive closure prologues): returns
/// (capture tuple, slot clone).
pub fn take_caps_self<T: std::any::Any + Send + Sync + Clone>(
    args: &mut Args,
) -> SourceResult<(T, StateSlot)> {
    let value: Value = args.expect("__trust_state")?;
    match value {
        Value::Dyn(dynamic) => match dynamic.downcast::<StateSlot>() {
            Some(slot) => {
                let caps = slot
                    .inner
                    .clone()
                    .downcast::<T>()
                    .map(|arc| (*arc).clone())
                    .map_err(|_| {
                        state_error(&format!(
                            "state handle type mismatch (generator bug): expected {}",
                            std::any::type_name::<T>()
                        ))
                    })?;
                Ok((caps, slot.clone()))
            }
            None => Err(state_error("first positional argument is not a state handle (generator bug)")),
        },
        _ => Err(state_error("first positional argument is not a state handle (generator bug)")),
    }
}

/// Capture-tuple unpacking for stub closures (the StateSlot carries the
/// capture tuple rather than module state; take_state returns an Arc, and
/// destructuring the tuple by value costs one clone — the tuple is small,
/// the cost is negligible).
pub fn take_caps<T: std::any::Any + Send + Sync + Clone>(
    args: &mut Args,
) -> SourceResult<T> {
    let arc: std::sync::Arc<T> = take_state(args)?;
    Ok((*arc).clone())
}

/// Stub-closure capture unpacking: names not visible at creation time (the
/// Option is None) report unknown variable at call time (matching native
/// capture semantics).
pub fn cap(value: Option<Value>, name: &str, span: Span) -> SourceResult<Value> {
    match value {
        Some(value) => Ok(value),
        None => bail!(span, "unknown variable: {name}"),
    }
}

/// Named-argument binding for stub closures: the stub binding stage already
/// filled in defaults, so this always succeeds (mirrors `args.named`; a
/// missing argument reports missing argument — only a bare call can trigger
/// it).
pub fn param_named(args: &mut Args, name: &str, span: Span) -> SourceResult<Value> {
    match args.named::<Value>(name)? {
        Some(value) => Ok(value),
        None => bail!(span, "missing argument: {name}"),
    }
}

/// Checks for leftover arguments after parameter binding (mirrors
/// `Args::finish`).
pub fn finish(args: &mut Args, _span: Span) -> SourceResult<()> {
    if let Some(arg) = args.items.first() {
        match &arg.name {
            Some(name) => bail!(arg.span, "unexpected argument: {name}"),
            None => bail!(arg.span, "unexpected argument"),
        }
    }
    Ok(())
}

/// Builds a named argument (used by generated code at call sites; `span` is
/// the argument item's span, `value_span` the value expression's span;
/// mirrors native `Eval for ast::Args`).
pub fn named_arg(span: Span, value_span: Span, name: &str, value: Value) -> Arg {
    Arg {
        span,
        name: Some(name.into()),
        value: Spanned::new(value, value_span),
    }
}

/// Spreads arguments (`f(..args)`; mirrors `Eval for ast::Arg::Spread`:
/// arrays by position, dictionaries by name, None skipped).
pub fn spread_args(args: &mut Args, span: Span, value: Value) -> SourceResult<()> {
    match value {
        Value::None => Ok(()),
        Value::Array(array) => {
            for item in array {
                args.push(span, item);
            }
            Ok(())
        }
        Value::Dict(dict) => {
            for (key, value) in dict {
                args.items.push(named_arg(span, span, &key, value));
            }
            Ok(())
        }
        Value::Args(inner) => {
            for item in inner.items.iter() {
                args.items.push(item.clone());
            }
            Ok(())
        }
        other => bail!(span, "cannot spread {}", other.ty()),
    }
}

/// Array construction convenience (the generated code's equivalent of the
/// `array!` macro).
pub fn array(values: Vec<Value>) -> Array {
    Array::from_iter(values)
}

/// Dictionary construction helper (generated code inserts key by key,
/// preserving source order).
pub fn dict_put(dict: &mut typst::foundations::Dict, key: &str, value: Value) {
    dict.insert(key.into(), value);
}

/// Dictionary item with an expression key (`("a" + x: v)`; mirrors
/// `Eval for ast::DictItem::Keyed`: the key is evaluated then cast to a
/// string, with errors reported at the key expression's span).
pub fn dict_put_key(
    dict: &mut typst::foundations::Dict,
    key: Value,
    value: Value,
    span: Span,
) -> SourceResult<()> {
    let key: Str = key.cast().at(span)?;
    dict.insert(key, value);
    Ok(())
}

/// Dictionary spread `(..other)` (mirrors `Eval for ast::DictItem::Spread`).
pub fn dict_spread(
    dict: &mut typst::foundations::Dict,
    value: Value,
    span: Span,
) -> SourceResult<()> {
    match value {
        Value::None => Ok(()),
        Value::Dict(other) => {
            for (key, value) in other {
                dict.insert(key, value);
            }
            Ok(())
        }
        other => bail!(span, "cannot spread {} into dictionary", other.ty()),
    }
}

/// Empty scope (the initial value for generated code's
/// NativeFuncData::scope).
pub fn empty_scope() -> Scope {
    Scope::new()
}

/// Any-return-type description (the initial value for generated code's
/// NativeFuncData::returns).
pub fn any_cast_info() -> typst::foundations::CastInfo {
    typst::foundations::CastInfo::Any
}

/// Array spread `(..other)` (the generated code's array-literal spread).
pub fn array_spread(values: &mut Vec<Value>, value: Value, span: Span) -> SourceResult<()> {
    match value {
        Value::None => Ok(()),
        Value::Array(array) => {
            values.extend(array);
            Ok(())
        }
        Value::Args(args) => {
            values.extend(args.items.into_iter().map(|arg| arg.value.v));
            Ok(())
        }
        other => bail!(span, "cannot spread {} into array", other.ty()),
    }
}

/// In-place invocation of mutable methods (push/pop/insert/remove); mirrors
/// `typst-eval/src/methods.rs::call_method_mut` (errors carry the method
/// call's tracepoint, same as native).
pub fn method_mut(
    engine: &mut Engine,
    value: &mut Value,
    method: &str,
    mut args: Args,
    span: Span,
) -> SourceResult<Value> {
    let ty = value.ty();
    let mut output = Value::None;
    match value {
        Value::Array(array) if matches!(method, "push" | "pop" | "insert" | "remove") => {
            match method {
                "push" => array.push(args.expect("value")?),
                "pop" => output = array.pop().at(span)?,
                "insert" => array
                    .insert(args.expect("index")?, args.expect("value")?)
                    .at(span)?,
                _ => {
                    output = array
                        .remove(args.expect("index")?, args.named("default")?)
                        .at(span)?
                }
            }
        }
        Value::Dict(dict) if matches!(method, "insert" | "remove") => match method {
            "insert" => dict.insert(args.expect("key")?, args.expect("value")?),
            _ => {
                output = dict
                    .remove(args.expect("key")?, args.named("default")?)
                    .at(span)?
            }
        },
        // Mirrors maybe_resolve_mutating's dictionary fallback: push/pop are
        // **not** a dictionary's mutable methods (is_dict_mutating_method
        // only accepts insert/remove), so this falls through to a plain
        // field call — dictionary fields cannot be called directly (present
        // vs. missing key produce different errors, mirroring
        // eval_field_callee's dictionary branch).
        Value::Dict(dict) if matches!(method, "push" | "pop") => {
            let key = Str::from(method);
            return match dict.at(key, None) {
                Ok(_) => {
                    bail!(span, "cannot directly call dictionary keys as functions")
                }
                Err(err) => Err(err).at(span),
            }
        }
        _ => bail!(span, "type {ty} has no method `{method}`"),
    }
    args.finish()?;
    let name = EcoString::from(method);
    Ok(output).trace(
        engine.world,
        || typst::diag::Tracepoint::Call(Some(name.clone())),
        span,
    )
}

/// **Runtime dispatch** for mutable-method calls (mirrors the full shape
/// of `maybe_resolve_mutating`): the four array methods and dictionary
/// insert/remove mutate in place; dictionary push/pop errors as a field
/// call; **every other type falls back to a plain method/field call**
/// (symbol modifiers etc., mirroring eval_field_callee — `s.push(none)`
/// returns a new symbol rather than erroring). The value's type is unknown
/// at translation time, so the dispatch must happen at runtime, per value.
pub fn method_mut_dispatch(
    engine: &mut Engine,
    context: Tracked<Context>,
    value: &mut Value,
    method: &str,
    mut args: Args,
    span: Span,
    access_text: &str,
) -> SourceResult<Value> {
    let is_array = matches!(value, Value::Array(_));
    let is_dict = matches!(value, Value::Dict(_));
    if (is_array && matches!(method, "push" | "pop" | "insert" | "remove"))
        || (is_dict && matches!(method, "insert" | "remove"))
    {
        return method_mut(engine, value, method, args, span);
    }
    if is_dict {
        // Dictionary push/pop: the same branch inside method_mut reports the
        // field-call error.
        return method_mut(engine, value, method, args, span);
    }
    // Fall back to a plain field call: a method call passes the target as
    // the first positional argument.
    let target = value.clone();
    let (func, bound) = method_callee(target.clone(), method, access_text, engine, span)?;
    if bound.is_some() {
        args.insert(0, span, target);
    }
    let name = EcoString::from(method);
    call_with(func, None, span, args, engine, context).trace(
        engine.world,
        move || typst::diag::Tracepoint::Call(Some(name.clone())),
        span,
    )
}

// --- Content translation helpers (mirroring the construction in
// typst-eval/src/markup.rs) ---

/// A text run.
pub fn text(s: &str) -> typst::foundations::Content {
    typst::text::TextElem::packed(typst::foundations::Str::from(s))
}

/// A space.
pub fn space() -> typst::foundations::Content {
    typst::text::SpaceElem::shared().clone()
}

/// A soft linebreak `\`.
pub fn linebreak() -> typst::foundations::Content {
    typst::text::LinebreakElem::shared().clone()
}

/// A paragraph break.
pub fn parbreak() -> typst::foundations::Content {
    typst::model::ParbreakElem::shared().clone()
}

/// Markup sequence composition (mirrors `Content::sequence`).
pub fn content_sequence(parts: Vec<typst::foundations::Content>) -> typst::foundations::Content {
    typst::foundations::Content::sequence(parts)
}

/// Converts an embedded expression's value to content (mirrors the display
/// semantics of `#expr` in markup).
pub fn embed(value: Value) -> typst::foundations::Content {
    value.display()
}

/// Iterator-shaped loop sources (mirrors `Eval for ast::ForLoop`: arrays
/// consumed by value, dictionaries as key-value pairs, strings by grapheme,
/// byte strings by byte; all streaming, zero materialization —
/// dictionaries/strings/byte strings yield lazily) for generated code's
/// inline `for` (break/continue work natively). Combinations of
/// destructuring patterns with Str/Bytes are guaranteed absent by the
/// caller at translation time (native errors on them too). The iterator
/// borrows `value` (in generated code the loop-source temporary lives for
/// the whole for statement).
pub fn iter_values<'a>(
    value: &'a Value,
    span: Span,
) -> SourceResult<Box<dyn Iterator<Item = Value> + 'a>> {
    use unicode_segmentation::UnicodeSegmentation;
    Ok(match value {
        Value::Array(array) => Box::new(array.clone().into_iter()),
        Value::Dict(dict) => Box::new(dict.iter().map(|(key, item): (&Str, &Value)| {
            Array::from_iter([key.clone().into_value(), item.clone()]).into_value()
        })),
        Value::Str(string) => Box::new(
            string
                .as_str()
                .graphemes(true)
                .map(|g| Value::Str(g.into())),
        ),
        Value::Bytes(bytes) => Box::new(
            bytes
                .as_slice()
                .iter()
                .map(|b| Value::Int(*b as i64)),
        ),
        other => bail!(span, "cannot loop over {}", other.ty()),
    })
}

// --- Destructuring helpers (mirroring the semantics and error messages of
// typst-eval/src/binding.rs) ---

/// Array destructuring: the i-th element (errors when short).
pub fn d_at(array: &typst::foundations::Array, i: usize, span: Span) -> SourceResult<Value> {
    match array.at(i as i64, None) {
        Ok(value) => Ok(value),
        Err(_) => Err(elements_mismatch_diagnostic(
            array.len(),
            i + 1,
            false,
            span,
        )),
    }
}

/// Array destructuring sink collection (`..rest`); `total` is the number of
/// positions the pattern consumes.
/// Array destructuring sink size (mirrors binding.rs's
/// `(1 + len).checked_sub(items)`): a shortfall is an element-count error.
pub fn d_sink_size(
    array: &typst::foundations::Array,
    total: usize,
    span: Span,
) -> SourceResult<usize> {
    match (1 + array.len()).checked_sub(total) {
        Some(size) => Ok(size),
        None => Err(elements_mismatch_diagnostic(
            array.len(),
            total - 1,
            true,
            span,
        )),
    }
}

/// Array destructuring sink slice (`size` items from `i`; out of bounds is
/// an element-count error; `count` is the number of non-sink items in the
/// pattern, used only in the error message).
pub fn d_rest(
    array: &typst::foundations::Array,
    i: usize,
    size: usize,
    count: usize,
    span: Span,
) -> SourceResult<typst::foundations::Array> {
    match array.as_slice().get(i..i + size) {
        Some(slice) => Ok(slice.iter().cloned().collect()),
        None => Err(elements_mismatch_diagnostic(array.len(), count, true, span)),
    }
}

/// Post-destructuring validation for arrays (leftover elements error;
/// `consumed` is the runtime index).
pub fn d_array_finish(
    array: &typst::foundations::Array,
    consumed: &usize,
    span: Span,
) -> SourceResult<()> {
    if *consumed < array.len() {
        return Err(elements_mismatch_diagnostic(
            array.len(),
            *consumed,
            false,
            span,
        ));
    }
    Ok(())
}

/// Dictionary destructuring: fetch by key (via `Dict::get`, keeping the
/// original hint).
pub fn d_get(dict: &typst::foundations::Dict, key: &str, span: Span) -> SourceResult<Value> {
    dict.get(key).cloned().at(span)
}

/// Dictionary destructuring sink collection (`..rest`, excluding used
/// keys).
pub fn d_dict_rest(dict: &typst::foundations::Dict, used: &[&str]) -> typst::foundations::Dict {
    let mut rest = typst::foundations::Dict::new();
    for (key, value) in dict.iter() {
        if !used.iter().any(|u| *u == key.as_str()) {
            rest.insert(key.clone(), value.clone());
        }
    }
    rest
}

/// Mirrors the original `wrong_number_of_elements`: main message + hint
/// (count semantics live in the hint, verbatim as in typst-eval).
fn elements_mismatch_diagnostic(
    len: usize,
    expected_count: usize,
    spread: bool,
    span: Span,
) -> EcoVec<SourceDiagnostic> {
    let quantifier = if len > expected_count {
        "too many"
    } else {
        "not enough"
    };
    let expected = match (spread, expected_count) {
        (true, 1) => "at least 1 element".to_string(),
        (true, c) => format!("at least {c} elements"),
        (false, 0) => "an empty array".to_string(),
        (false, 1) => "a single element".to_string(),
        (false, c) => format!("{c} elements"),
    };
    eco_vec![
        SourceDiagnostic::error(
            span,
            typst::foundations::Str::from(format!("{quantifier} elements to destructure"))
        )
        .with_hint(format!(
            "the provided array has a length of {len}, but the pattern expects {expected}"
        ))
    ]
}

/// Imports an external package at runtime (untranslated dependencies run
/// through the interpreter — mixed execution; mirrors typst-eval's
/// `import_package` + `import_file`: sink/route are passed through (warnings
/// and call depth share the same chain), cycle detection, and the module is
/// bound under the package's short name).
pub fn import_external(engine: &mut Engine, spec: &str, span: Span) -> SourceResult<Module> {
    // Direct reuse of the pub `typst_eval::import` (a hand-rolled version
    // drifted in three places: the spec-parse error message, the manifest
    // validation chain, and the package-name mapping — the original gets
    // all of them right).
    typst_eval::import(engine, spec, span)
}

/// Explicit degradation marker: emits a warning and returns none (the
/// no-silent-degradation principle — the generated artifact lacks
/// functionality here, and the user must see it).
pub fn degraded(engine: &mut Engine, message: &str) -> SourceResult<Value> {
    let diagnostic = typst::diag::SourceDiagnostic::warning(
        Span::detached(),
        typst::foundations::Str::from(format!("trust degraded: {message}")),
    );
    engine.sink.warn(diagnostic);
    Ok(Value::None)
}

/// The **error** form of a translation-time degradation point (a semantic
/// error rather than a missing feature: break/continue outside a loop,
/// etc.; complements [`degraded`]'s warning form; the message follows
/// typst's original wording, and the error tests match on the message).
pub fn bail_value(_engine: &mut Engine, message: &str) -> SourceResult<Value> {
    Err(eco_vec![SourceDiagnostic::error(
        Span::detached(),
        eco_format!("{message}"),
    )])
}

/// Path segments of mutable places (assignment / mutable-method targets),
/// mirroring typst-eval's `access.rs`: field access and accessor methods
/// (`first`/`last`/`at`).
///
/// typst semantics (`call_method_access` / `access_dict`):
/// - a field segment requires the current value to be a dictionary
///   (`Dict::at_mut`; a missing key errors with a hint);
/// - an `at` segment takes an integer index on arrays, a string key on
///   dictionaries;
/// - `first`/`last` are array-only.
pub enum PlaceSeg {
    /// Dictionary field name (the escaped literal from generation time).
    Field(String),
    /// The index/key for `at` (a `Value` evaluated by generated code).
    At(Value),
    First,
    Last,
}

// --- Lvalue access gate (mirrors typst-eval/src/access.rs and
// Scopes::get_mut) ---
//
// typst concentrates mutability checks in two places: `Binding::write` is
// the sole write gate (the Captured variant reports the read-only error
// according to the capturer), and `Scopes::get_mut`'s miss branch decides
// between a "constant" and an "unknown variable" error based on whether the
// name hits the globals. We reuse typst's pub types directly to trigger the
// same error construction — zero message drift.

/// Assignment / mutable method landing on a **captured binding**: mirrors
/// `Binding::write`'s rejection of `BindingKind::Captured` — construct a
/// Captured binding and call its `write`; the error message (including the
/// function/context expression wording variants) is generated by typst
/// itself.
pub fn bail_captured(capturer: Capturer) -> SourceResult<Value> {
    let err = Binding::detached(Value::None)
        .capture(capturer)
        .write()
        .unwrap_err();
    Err(eco_vec![SourceDiagnostic::error(Span::detached(), err)])
}

/// Assignment target is a **non-lvalue expression**: evaluate side effects
/// first, then error; mirrors the fallback arm of `Access for ast::Expr`
/// (`access.rs:21-24`).
pub fn bail_temporary(span: Span) -> SourceResult<Value> {
    bail!(span, "cannot mutate a temporary value")
}

/// Identifier assignment target missing from every lexical scope: mirrors
/// `Scopes::get_mut`'s miss branch — build `Scopes` with an empty local
/// scope + the global library and call its `get_mut` directly; hitting the
/// globals yields "cannot mutate a constant: {name}" (the `std` special
/// case included), otherwise "unknown variable: {name}" (minus hint
/// included).
pub fn check_mut_unknown(
    engine: &mut Engine,
    name: &str,
    span: Span,
) -> SourceResult<()> {
    let library: &Library = engine.library;
    Scopes::new(Some(library))
        .get_mut(name)
        .map(|_| ())
        .at(span)?;
    Ok(())
}

/// Evaluation of plain assignments `a.b..k = v` (mirrors
/// `apply_assignment`'s FieldAccess special case: after `access_dict` walks
/// to the **last segment** it inserts directly into the dictionary — a
/// missing key is created, a single hashed write; intermediate segments
/// behave as in [`place_mut`], with at_mut errors). A non-field last
/// segment (at/first/last) takes a mutable reference with [`place_mut`]
/// semantics and writes through it.
pub fn assign_value(
    root: &mut Value,
    path: &[PlaceSeg],
    value: Value,
    span: Span,
) -> SourceResult<()> {
    let Some((last, init)) = path.split_last() else {
        *root = value;
        return Ok(());
    };
    if let PlaceSeg::Field(name) = last {
        let parent = place_mut(root, init, span)?;
        if let Value::Dict(dict) = parent {
            dict.insert(Str::from(name.as_str()), value);
            return Ok(());
        }
    }
    // Non-dictionary-field last segment: the general mutable place
    // (at/first/last or a non-dictionary host).
    *place_mut(root, path, span)? = value;
    Ok(())
}

/// Walks the path segments to a mutable reference (mirrors `Expr::access`;
/// field-segment error messages mirror `access_dict`'s three-way branch).
pub fn place_mut<'a>(
    root: &'a mut Value,
    path: &[PlaceSeg],
    span: Span,
) -> SourceResult<&'a mut Value> {
    let mut current = root;
    for seg in path {
        current = match seg {
            PlaceSeg::Field(name) => match current {
                Value::Dict(dict) => dict.at_mut(name).at(span)?,
                value => access_dict_error(value, span)?,
            },
            PlaceSeg::At(key) => match current {
                Value::Array(array) => {
                    let index: i64 = key.clone().cast().at(span)?;
                    array.at_mut(index).at(span)?
                }
                Value::Dict(dict) => {
                    let key: typst::foundations::Str = key.clone().cast().at(span)?;
                    dict.at_mut(&key).at(span)?
                }
                value => {
                    let ty = value.ty();
                    if ty.scope().get("at").is_some() {
                        bail!(span, "cannot mutate a temporary value")
                    }
                    bail!(span, "type {ty} has no method `at`")
                }
            },
            PlaceSeg::First => match current {
                Value::Array(array) => array.first_mut().at(span)?,
                value => {
                    let ty = value.ty();
                    if ty.scope().get("first").is_some() {
                        bail!(span, "cannot mutate a temporary value")
                    }
                    bail!(span, "type {ty} has no method `first`")
                }
            },
            PlaceSeg::Last => match current {
                Value::Array(array) => array.last_mut().at(span)?,
                value => {
                    let ty = value.ty();
                    if ty.scope().get("last").is_some() {
                        bail!(span, "cannot mutate a temporary value")
                    }
                    bail!(span, "type {ty} has no method `last`")
                }
            },
        };
    }
    Ok(current)
}

/// Non-dictionary branch of mutable field access (mirrors `access_dict`'s
/// three-way split: dedicated getter types / types without fields / static
/// fields not open for mutation).
fn access_dict_error(value: &mut Value, span: Span) -> SourceResult<&mut Value> {
    let ty = value.ty();
    if matches!(
        value,
        Value::Symbol(_) | Value::Content(_) | Value::Module(_) | Value::Func(_) | Value::Args(_)
    ) {
        bail!(span, "cannot mutate fields on {ty}");
    }
    if typst::foundations::fields_on(ty).is_empty() {
        bail!(span, "{ty} does not have accessible fields");
    }
    Err(eco_format!("fields on {ty} are not yet mutable"))
        .hint(eco_format!(
            "try creating a new {ty} with the updated field value instead"
        ))
        .at(span)
}

/// Opaque handle for per-build state: wraps an `Arc<dyn Any + Send +
/// Sync>` into typst's value world (`Value::Dyn`) and travels with the
/// function value (mirroring the captured data layout of typst closures);
/// the native body unpacks it from the first positional argument via
/// [`take_state`].
#[derive(Clone)]
pub struct StateSlot {
    /// Monotonic instance id (a global counter): identity semantics.
    /// **Pointer hashing must not be used** — after a slot is freed the
    /// allocator reuses the address (ABA), two distinct instances would
    /// compare equal, their comemo memo keys would collide, and answers
    /// would leak across instances (one instance's cached result returned
    /// for another's call).
    id: u64,
    inner: std::sync::Arc<dyn std::any::Any + Send + Sync>,
}

impl StateSlot {
    /// Wraps a piece of state / a capture tuple.
    pub fn new<T: std::any::Any + Send + Sync>(state: std::sync::Arc<T>) -> Self {
        static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
        Self {
            id: NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed),
            inner: state,
        }
    }
}

impl std::fmt::Debug for StateSlot {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("state slot")
    }
}

impl typst::foundations::Repr for StateSlot {
    fn repr(&self) -> EcoString {
        "state slot".into()
    }
}

impl typst::foundations::NativeType for StateSlot {
    const NAME: &'static str = "state";
    fn data() -> &'static typst::foundations::NativeTypeData {
        static DATA: std::sync::OnceLock<typst::foundations::NativeTypeData> =
            std::sync::OnceLock::new();
        DATA.get_or_init(|| typst::foundations::NativeTypeData {
            name: "state",
            long_name: "state",
            title: "State",
            docs: "internal per-build state slot",
            def_site: typst::utils::DefSite {
                path: "trust-runtime",
                key: "StateSlot",
            },
            keywords: &[],
            constructor: std::sync::LazyLock::new(|| None),
            scope: std::sync::LazyLock::new(typst::foundations::Scope::new),
        })
    }
}

impl PartialEq for StateSlot {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

impl std::hash::Hash for StateSlot {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.id.hash(state);
    }
}

/// Stub direct-call routine: the native-body entry (same type as
/// `NativeFuncData.function`: `&'static dyn Fn`) carried by the third
/// binding `__trust_routine` of a stub's captured scope, plus the
/// named-argument defaults table (parameter name × creation-time
/// materialized value; mirrors typst closures' `closure.defaults`).
/// [`trust_eval_closure`]'s fast path uses this to recognize our stubs,
/// inject defaults for missing named arguments (mirroring `eval_closure`'s
/// `default.clone()` at binding time), and call the native body directly
/// instead of the memoized interpretation.
#[derive(Clone)]
pub struct TrustRoutine {
    pub f: &'static (dyn Fn(
        &mut Engine,
        Tracked<'_, Context>,
        &mut Args,
    ) -> SourceResult<Value>
        + Send
        + Sync),
    /// (named-argument name, creation-time default), in declaration order.
    /// The fast path injects only items the caller did not provide;
    /// provided ones are skipped (injected items go before the caller's
    /// arguments, and `Args::named`'s "last one wins for the same name"
    /// semantics keeps the caller's value in effect).
    pub defaults: Vec<(Str, Value)>,
}

impl std::fmt::Debug for TrustRoutine {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("trust routine")
    }
}

impl typst::foundations::Repr for TrustRoutine {
    fn repr(&self) -> EcoString {
        "trust routine".into()
    }
}

impl typst::foundations::NativeType for TrustRoutine {
    const NAME: &'static str = "routine";
    fn data() -> &'static typst::foundations::NativeTypeData {
        static DATA: std::sync::OnceLock<typst::foundations::NativeTypeData> =
            std::sync::OnceLock::new();
        DATA.get_or_init(|| typst::foundations::NativeTypeData {
            name: "routine",
            long_name: "routine",
            title: "Routine",
            docs: "internal stub direct-call routine",
            def_site: typst::utils::DefSite {
                path: "trust-runtime",
                key: "TrustRoutine",
            },
            keywords: &[],
            constructor: std::sync::LazyLock::new(|| None),
            scope: std::sync::LazyLock::new(typst::foundations::Scope::new),
        })
    }
}

impl PartialEq for TrustRoutine {
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(
            self.f as *const _ as *const (),
            other.f as *const _ as *const (),
        ) && self.defaults == other.defaults
    }
}

impl std::hash::Hash for TrustRoutine {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        (self.f as *const _ as *const () as usize).hash(state);
        self.defaults.hash(state);
    }
}

/// Extracts named-argument names from the stub node in declaration order
/// and pairs them with the creation-time materialized defaults table
/// (mirrors typst closures' `closure.defaults`); a count mismatch (a change
/// in the generator's output shape) yields an empty table — the fast path
/// then injects nothing and semantics fall back to the stub's own binding.
fn stub_named_defaults(
    node: &typst_syntax::SyntaxNode,
    defaults: &[Value],
) -> Vec<(Str, Value)> {
    let Some(closure_node) = find_closure_node(node) else {
        return Vec::new();
    };
    let Some(closure) = closure_node.cast::<ast::Closure>() else {
        return Vec::new();
    };
    let names: Vec<&str> = closure
        .params()
        .children()
        .filter_map(|param| match param {
            ast::Param::Named(named) => Some(named.name().as_str()),
            _ => None,
        })
        .collect();
    if names.len() != defaults.len() {
        return Vec::new();
    }
    names
        .into_iter()
        .zip(defaults.iter().cloned())
        .map(|(name, value)| (Str::from(name), value))
        .collect()
}

/// Stub captured scope (three protocol bindings: the native-body function
/// value + the direct-call routine + the state handle).
fn stub_scope(
    data: &'static typst::foundations::NativeFuncData,
    node: &typst_syntax::SyntaxNode,
    defaults: &[Value],
    // None = a stateless function (the body has no take_state prologue):
    // no state handle is carried, and neither the fast nor slow path
    // inserts a state argument. **Whether a function is native is an
    // externally invisible implementation detail** — all translated
    // functions use a uniform Closure-shaped stub (mirroring original user
    // closures where `Func::scope()` is None; a bare Native would leak the
    // identity, since import dispatch distinguishes user closures by
    // scope()).
    state: Option<&StateSlot>,
) -> Scope {
    let mut scope = Scope::new();
    scope.define("__trust_impl", Func::from(data));
    scope.define(
        "__trust_routine",
        Value::Dyn(typst::foundations::Dynamic::new(TrustRoutine {
            f: data.function.0,
            defaults: stub_named_defaults(node, defaults),
        })),
    );
    if let Some(state) = state {
        scope.define(
            "__trust_state",
            Value::Dyn(typst::foundations::Dynamic::new(state.clone())),
        );
    }
    scope
}

/// Signature-faithful stub closure (the native-closure stub approach): the
/// original `{name}{params}` signature is preserved (parameter checks /
/// `params()` / repr / default introspection all faithful); the forwarding
/// body passes the state handle to the native implementation as the first
/// positional argument. `defaults` holds creation-time materialized values
/// (mirroring typst closures evaluating defaults at creation time; a
/// missing argument at call time is taken from defaults — the AST's default
/// expressions are never evaluated). State travels with the function value,
/// with the same lifetime — global-registry addressing is thereby retired.
/// Per-call-site static stub creation (the node is already parsed and
/// cached by the call site's `static LazyLock`, so this takes no lookup and
/// no lock: Scope construction + define + Func::from).
pub fn native_closure_node(
    data: &'static typst::foundations::NativeFuncData,
    node: &(typst_syntax::SyntaxNode, usize),
    defaults: Vec<Value>,
    state: Option<&StateSlot>,
) -> Func {
    let (node, num_pos_params) = node.clone();
    let scope = stub_scope(data, &node, &defaults, state);
    let closure_span = node.span();
    Func::from(Closure {
        node: ClosureNode::Closure(node),
        defaults,
        captured: scope,
        num_pos_params,
    })
    .spanned(closure_span)
}

pub fn native_closure(
    data: &'static typst::foundations::NativeFuncData,
    params_src: &str,
    defaults: Vec<Value>,
    // None = a stateless function: the stub is still constructed (Closure
    // shape preserves identity) but carries/forwards no state.
    state: Option<&StateSlot>,
) -> Func {
    let (params, arg_list) = stub_signature(params_src);
    let src = stub_source(data.name, &params, &arg_list, state.is_some());
    let (node, num_pos_params) = cached_closure_node(&src);
    let scope = stub_scope(data, &node, &defaults, state);
    let closure_span = node.span();
    Func::from(Closure {
        node: ClosureNode::Closure(node),
        defaults,
        captured: scope,
        num_pos_params,
    })
    .spanned(closure_span)
}

/// Stub source composition (a pure function, uncached): `stub_signature`
/// (pattern parameters → synthesized names, unnamed sinks get a name) +
/// `stub_source` merged — called at **translation time**; the generated
/// code embeds the result as a literal in each call site's static.
pub fn compose_stub(name: &str, params_src: &str) -> String {
    let (params, args) = stub_signature(params_src);
    stub_source(name, &params, &args, true)
}

/// Stub signature and forwarding argument list (cached by `params_src`
/// text — stub creation is frequent, so parsing happens only once).
///
/// Pattern parameters (destructuring parameters) are replaced in the
/// signature by the synthesized name `__trust_pN` (the forwarding signature
/// must bind the names the forwarding body references; the destructuring
/// itself is done by the native body); an unnamed sink `..` gets the
/// synthesized name `__trust_sink`.
fn stub_signature(params_src: &str) -> (String, String) {
    static CACHE: std::sync::LazyLock<
        std::sync::RwLock<std::collections::HashMap<String, (String, String)>>,
    > = std::sync::LazyLock::new(|| std::sync::RwLock::new(std::collections::HashMap::new()));
    if let Some(hit) = CACHE.read().unwrap().get(params_src) {
        return hit.clone();
    }
    let root = typst_syntax::parse_code(&format!("let f{params_src} = none"));
    let (mut params, mut args): (Vec<String>, Vec<String>) = (Vec::new(), Vec::new());
    if let Some(closure_node) = find_closure_node(&root)
        && let Some(closure) = closure_node.cast::<ast::Closure>()
    {
        let mut nth_pattern = 0usize;
        for param in closure.params().children() {
            let text = param.to_untyped().full_text().to_string();
            match param {
                ast::Param::Pos(ast::Pattern::Normal(ast::Expr::Ident(_))) => {
                    args.push(text.clone());
                    params.push(text);
                }
                ast::Param::Pos(ast::Pattern::Placeholder(_)) => {
                    args.push(text.clone());
                    params.push(text);
                }
                ast::Param::Pos(_) => {
                    // Destructuring parameter: the signature binds a
                    // synthesized name; the native body destructures
                    // itself.
                    let name = format!("__trust_p{nth_pattern}");
                    nth_pattern += 1;
                    args.push(name.clone());
                    params.push(name);
                }
                ast::Param::Named(named) => {
                    let name = named.name().as_str();
                    args.push(format!("{name}: {name}"));
                    params.push(text);
                }
                ast::Param::Spread(spread) => match spread.sink_ident() {
                    Some(ident) => {
                        args.push(format!("..{}", ident.as_str()));
                        params.push(text);
                    }
                    None => {
                        args.push("..__trust_sink".to_string());
                        // Unnamed sink: the text looks like `..`; give it
                        // a synthesized name.
                        let named = if text.trim() == ".." {
                            "..__trust_sink".to_string()
                        } else {
                            text.replace("..", "..__trust_sink")
                        };
                        params.push(named);
                    }
                },
            }
        }
    }
    let out = (params.join(", "), args.join(", "));
    CACHE
        .write()
        .unwrap()
        .insert(params_src.to_string(), out.clone());
    out
}

/// Stub source `let {name}({params}) = __trust_impl(__trust_state, {args})`
/// cached by (function name, signature) (zero formatting on the frequent
/// creation path).
fn stub_source(name: &str, params: &str, args: &str, stateful: bool) -> String {
    static CACHE: std::sync::LazyLock<
        std::sync::RwLock<
            std::collections::HashMap<String, std::collections::HashMap<(String, bool), String>>,
        >,
    > = std::sync::LazyLock::new(|| std::sync::RwLock::new(std::collections::HashMap::new()));
    let key = (params.to_string(), stateful);
    if let Some(inner) = CACHE.read().unwrap().get(name)
        && let Some(hit) = inner.get(&key)
    {
        return hit.clone();
    }
    // Stateful: forward the state handle as the first argument; stateless:
    // pass arguments straight through (the body has no take_state).
    let src = if stateful {
        format!("let {name}({params}) = __trust_impl(__trust_state, {args})")
    } else {
        format!("let {name}({params}) = __trust_impl({args})")
    };
    CACHE
        .write()
        .unwrap()
        .entry(name.to_string())
        .or_default()
        .insert(key, src.clone());
    src
}

/// Native body prologue: unpack the per-build state from the first
/// positional argument and remove it from the arguments (mirroring the
/// stub forwarding: `__trust_impl(__trust_state, ..user args)`).
pub fn take_state<T: std::any::Any + Send + Sync>(
    args: &mut Args,
) -> SourceResult<std::sync::Arc<T>> {
    let value: Value = args.expect("__trust_state")?;
    match value {
        Value::Dyn(dynamic) => match dynamic.downcast::<StateSlot>() {
            Some(slot) => match slot.inner.clone().downcast::<T>() {
                Ok(arc) => Ok(arc),
                Err(_) => Err(state_error(&format!(
                    "state handle type mismatch (generator bug): expected {}",
                    std::any::type_name::<T>()
                ))),
            },
            None => Err(state_error("first positional argument is not a state handle (generator bug)")),
        },
        _ => Err(state_error("first positional argument is not a state handle (generator bug)")),
    }
}

// Style rule primitives (mirroring typst-eval/src/rules.rs): evaluation
// **only constructs**, never applies — a set rule builds `Styles`, a show
// rule builds `Recipe`; the actual transformation happens in typst's
// realize/layout (shared by generated code and interpreter alike).

/// `#set elem(..)`: builds the style sheet (mirrors `Eval for
/// ast::SetRule`'s `target.set(engine, args)`).
pub fn set_rule(
    target: Value,
    args: Args,
    span: Span,
    engine: &mut Engine,
) -> SourceResult<typst::foundations::Styles> {
    let func = target.cast::<Func>().at(span)?;
    let element = func
        .to_element()
        .ok_or_else(|| eco_format!("only element functions can be used in set rules"))
        .at(span)?;
    Ok(element.set(engine, args)?.spanned(span).liftable())
}

/// An empty style sheet (when a set rule's condition is false; mirrors
/// `Ok(Styles::new())`).
pub fn styles_empty() -> typst::foundations::Styles {
    typst::foundations::Styles::new()
}

/// `#show selector?: transform`: builds the recipe (mirrors `Eval for
/// ast::ShowRule`: the selector is cast to `ShowableSelector` (a
/// non-showable selector errors with the original cast message at the
/// selector's span); also carries the original `show page` no-effect
/// warning and the `show par: set block(spacing: ..)` migration warning).
pub fn show_rule(
    selector: Option<Value>,
    sel_span: Span,
    transform: Value,
    span: Span,
    engine: &mut Engine,
) -> SourceResult<typst::foundations::Recipe> {
    let selector = selector
        .map(|value| value.cast::<typst::foundations::ShowableSelector>().at(sel_span))
        .transpose()?
        .map(|selector| selector.0);
    let transform = transform.cast::<Transformation>().at(span)?;
    let recipe = typst::foundations::Recipe::new(selector, transform, span);
    check_show_rules(engine, &recipe);
    Ok(recipe)
}

/// `#show selector?: set ..`: the transform is styles (mirrors
/// `Transformation::Style(set.eval(..)?)`).
pub fn show_rule_style(
    selector: Option<Value>,
    sel_span: Span,
    styles: typst::foundations::Styles,
    span: Span,
    engine: &mut Engine,
) -> SourceResult<typst::foundations::Recipe> {
    let selector = selector
        .map(|value| value.cast::<typst::foundations::ShowableSelector>().at(sel_span))
        .transpose()?
        .map(|selector| selector.0);
    let recipe = typst::foundations::Recipe::new(selector, Transformation::Style(styles), span);
    check_show_rules(engine, &recipe);
    Ok(recipe)
}

/// The original's two show-rule warnings (mirrors `check_show_page_rule`
/// and `check_show_par_set_block`).
fn check_show_rules(engine: &mut Engine, recipe: &typst::foundations::Recipe) {
    if let Some(Selector::Elem(elem, _)) = recipe.selector()
        && *elem == typst::foundations::Element::of::<typst::layout::PageElem>()
    {
        engine.sink.warn(
            SourceDiagnostic::warning(
                recipe.span(),
                typst::foundations::Str::from(
                    "`show page` is not supported and has no effect",
                ),
            )
            .with_hint("customize pages with `set page(..)` instead"),
        );
    }
    if let Some(Selector::Elem(elem, _)) = recipe.selector()
        && *elem == typst::foundations::Element::of::<typst::model::ParElem>()
        && let Transformation::Style(styles) = recipe.transform()
    {
        let chain = typst::foundations::StyleChain::new(styles);
        if chain.has(typst::layout::BlockElem::above)
            || chain.has(typst::layout::BlockElem::below)
        {
            engine.sink.warn(
                SourceDiagnostic::warning(
                    recipe.span(),
                    typst::foundations::Str::from(
                        "`show par: set block(spacing: ..)` has no effect anymore",
                    ),
                )
                .with_hint("write `set par(spacing: ..)` instead")
                .with_hint(
                    "this is specific to paragraphs as they are not considered blocks anymore",
                ),
            );
        }
    }
}

/// Attaches styles to the tail content after a rule (mirrors eval_markup's
/// `tail.styled_with_map(styles)`).
pub fn styled_with_map(
    tail: typst::foundations::Content,
    styles: typst::foundations::Styles,
) -> typst::foundations::Content {
    tail.styled_with_map(styles)
}

/// Attaches a show rule to the tail content after a rule (mirrors
/// `tail.styled_with_recipe`; a rule without a selector applies
/// immediately).
pub fn styled_with_recipe(
    engine: &mut Engine,
    context: Tracked<Context>,
    tail: typst::foundations::Content,
    recipe: typst::foundations::Recipe,
) -> SourceResult<typst::foundations::Content> {
    tail.styled_with_recipe(engine, context, recipe)
}

/// Runtime wildcard layer for in-body `import <runtime value>: *` (mirrors
/// typst-eval's import.rs: a Func source without a scope reports "cannot
/// import from user-defined functions"; a Module/Type has its scope bound
/// name by name into the current scope, later-wins; other types get the
/// same error). Only wildcard imports whose static chain does not resolve
/// take this path; statically reachable ones stay fully static.
pub fn wild_import(value: &Value, at: Span) -> SourceResult<typst::foundations::Scope> {
    use typst::foundations::Scope;
    let source = match value {
        Value::Module(module) => module.scope(),
        Value::Type(ty) => ty.scope(),
        Value::Func(func) => func.scope().ok_or_else(|| {
            eco_vec![SourceDiagnostic::error(at, "cannot import from user-defined functions")]
        })?,
        v => {
            return Err(eco_vec![SourceDiagnostic::error(
                at,
                eco_format!("expected path, module, function, or type, found {}", v.ty()),
            )])
        }
    };
    let mut layer = Scope::new();
    for (name, binding) in source.iter() {
        layer.bind(name.clone(), binding.clone());
    }
    Ok(layer)
}

/// Name lookup across wildcard layers (innermost first): a hit returns the
/// value; a full miss with no fallback reports the same "unknown variable"
/// as typst.
pub fn wild_get(layers: &[&typst::foundations::Scope], name: &str, at: Span) -> SourceResult<Value> {
    wild_lookup(layers, name).ok_or_else(|| {
        eco_vec![SourceDiagnostic::error(at, eco_format!("unknown variable: {name}"))]
    })
}

fn wild_lookup(layers: &[&typst::foundations::Scope], name: &str) -> Option<Value> {
    layers
        .iter()
        .rev()
        .find_map(|scope| scope.get(name).map(|b| b.read().clone()))
}

/// Wildcard-layer lookup + static-chain fallback (when the name also has a
/// static binding: a layer hit wins, mirroring typst's scope chain —
/// wildcard names are bound into the inner scope and shadow the outer
/// ones).
pub fn wild_or(
    layers: &[&typst::foundations::Scope],
    name: &str,
    fallback: Value,
    _at: Span,
) -> SourceResult<Value> {
    Ok(wild_lookup(layers, name).unwrap_or(fallback))
}

/// Wildcard-layer lookup + global fallback (when the name has no static
/// binding).
pub fn wild_or_global(
    layers: &[&typst::foundations::Scope],
    name: &str,
    engine: &mut Engine,
    at: Span,
) -> SourceResult<Value> {
    wild_lookup(layers, name)
        .map(Ok)
        .unwrap_or_else(|| global(engine, name, at))
}

/// `@target` reference shorthand (mirrors typst-eval markup.rs's `Eval for
/// ast::Ref` → `RefElem::new(label)` + optional supplement; without it,
/// references and bibliographies render as nothing).
pub fn ref_elem(target: &str, supplement: Option<Value>) -> typst::foundations::Content {
    use typst::foundations::IntoValue;
    let label = typst::foundations::Label::construct(target.into())
        .unwrap_or_else(|_| panic!("reference target must not be empty: {target}"));
    let mut elem = typst::model::RefElem::new(label);
    if let Some(v) = supplement {
        elem.supplement.set(typst::foundations::Smart::Custom(Some(
            typst::model::Supplement::Content(v.display()),
        )));
    }
    match elem.into_value() {
        typst::foundations::Value::Content(c) => c,
        _ => unreachable!("RefElem packs to content"),
    }
}

/// Mutable module-slot helpers (top-level bindings modified in place; the
/// slot is a Mutex<Value>).
pub fn fill_ms(slot: &std::sync::Mutex<Value>, v: Value) -> SourceResult<()> {
    *slot.lock().unwrap() = v;
    Ok(())
}

pub fn read_ms(slot: &std::sync::Mutex<Value>) -> SourceResult<Value> {
    Ok(slot.lock().unwrap().clone())
}

pub fn write_ms(slot: &std::sync::Mutex<Value>, v: Value) -> SourceResult<()> {
    *slot.lock().unwrap() = v;
    Ok(())
}

/// `#context expr`: builds the deferred-evaluation closure (mirrors `Eval
/// for ast::Contextual`; evaluated during realize/layout with
/// location/styles).
pub fn context_closure(
    body_src: &str,
    captured: &[(&'static str, Value)],
    pending: &[(&'static str, bool)],
    engine: &mut Engine,
) -> Func {
    let node = cached_body_node(body_src);
    let scope = captured_scope(captured, pending, engine);
    Func::from(Closure {
        node: ClosureNode::Context(node.clone()),
        defaults: vec![],
        captured: scope,
        num_pos_params: 0,
    })
}

/// Snippet source → AST expression node (a lookup cache keyed by the
/// **original snippet text**; hits do zero formatting). A context body is
/// an **expression** (a code block or a single expression), so `parse_code`
/// takes the first expression under the Code root — the source must not be
/// wrapped in `#let` (under that root the first castable node is the
/// LetBinding itself: evaluation would run the body, but the returned value
/// is the let's none, which ContextElem displays as empty content). Both
/// the parsed and registered text are trimmed (leading/trailing trivia
/// would otherwise make the "first expression node" a Space).
fn cached_body_node(body_src: &str) -> typst_syntax::SyntaxNode {
    static CACHE: std::sync::LazyLock<
        std::sync::RwLock<std::collections::HashMap<String, typst_syntax::SyntaxNode>>,
    > = std::sync::LazyLock::new(|| std::sync::RwLock::new(std::collections::HashMap::new()));
    if let Some(hit) = CACHE.read().unwrap().get(body_src) {
        return hit.clone();
    }
    let text = body_src.trim().to_string();
    // Parse after wrapping in parentheses: the snippet has left its
    // original parse context — if it originally sat inside parentheses/a
    // block (a parameter default, an array element, a code block, ...),
    // newlines are mere trivia and the expression continues across lines;
    // top-level `parse_code` instead terminates the expression at a
    // newline (only else/. continue, mirroring parser.rs's
    // AtNewline::ContextualContinue), so a multi-line body would be
    // truncated to its first expression. Wrapping in a pair of parentheses
    // restores Continue semantics; the Parenthesized layer is then peeled
    // to take the inner expression (mirroring how typst-eval's `Eval for
    // ast::Contextual` directly holds the in-place body node).
    // CLOSURE_SOURCES registers the wrapped text, so spans correspond byte
    // for byte with the source.
    let wrapped = format!("({text})");
    let root = typst_syntax::parse_code(&wrapped);
    let first = root
        .children()
        .find(|child| child.cast::<ast::Expr>().is_some())
        .unwrap_or_else(|| panic!("context body parses to an expression: {text:?}"));
    let node = match first.cast::<ast::Expr>() {
        Some(ast::Expr::Parenthesized(paren)) => paren.expr().to_untyped().clone(),
        _ => first.clone(),
    };
    let n = CLOSURE_SOURCES.read().unwrap().len();
    let id = typst::syntax::RootedPath::new(
        typst::syntax::VirtualRoot::Project,
        typst::syntax::VirtualPath::new(format!("__trust_closure_{n}.typ"))
            .expect("valid closure path"),
    )
    .intern();
    CLOSURE_SOURCES.write().unwrap().push((id, wrapped.clone()));
    CACHE
        .write()
        .unwrap()
        .insert(body_src.to_string(), node.clone());
    node
}

/// Captured scope (pending materialization + the Captured read-only mark;
/// mirrors eval_closure's `scopes.top = closure.captured.clone()`).
fn captured_scope(
    captured: &[(&'static str, Value)],
    pending: &[(&'static str, bool)],
    engine: &mut Engine,
) -> Scope {
    let mut captured: Vec<(&'static str, Value)> = captured.to_vec();
    resolve_pending(engine, &mut captured, pending);
    let mut scope = Scope::new();
    for (name, value) in &captured {
        // Captured bindings get the read-only mark via `Binding::capture`
        // (mirroring typst closures' captured scope): write-captures like
        // `context (i = 1)` are rejected by typst's evaluator through
        // `Binding::write` with "variables from outside the context
        // expression are read-only...".
        scope.bind(
            (*name).into(),
            Binding::detached(value.clone()).capture(Capturer::Context),
        );
    }
    scope
}

/// Carrier element for context closures (mirrors
/// `ContextElem::new(func).pack()`; ContextElem implements IntoValue once
/// wrapped in `Packed`).
pub fn context_body(func: Func) -> typst::foundations::Content {
    use typst::foundations::IntoValue;
    match typst::foundations::ContextElem::new(func).into_value() {
        typst::foundations::Value::Content(content) => content,
        _ => unreachable!("ContextElem packs to content"),
    }
}

/// Label literal `<name>` (mirrors `Eval for ast::Label`).
pub fn label(name: &str) -> Value {
    let label = typst::foundations::Label::construct(name.into())
        .unwrap_or_else(|_| panic!("label name must not be empty: {name}"));
    Value::Label(label)
}

/// **Math expressions** outside the v1 language subset (Equation): their
/// volume is large but they pose almost no performance problem — they are
/// **interpreted** by typst-eval from a source snippet (the same fidelity
/// path as interpreted closures: a ContextNode closure + captured scope,
/// with snippets parse-cached by text). Other gaps do not take this path
/// and still degrade with a translation-time diagnostic.
pub fn eval_expr(
    src: &str,
    captured: &[(&'static str, Value)],
    pending: &[(&'static str, bool)],
    engine: &mut Engine,
    context: Tracked<Context>,
) -> SourceResult<Value> {
    let func = context_closure(src, captured, pending, engine);
    func.call::<[Value; 0]>(engine, context, [])
}

/// Interprets an **import statement** (glue; mirrors `Eval for
/// ast::ModuleImport` — import.rs:15-178, a private trait impl, driven
/// directly through the pub `Vm`/`Eval`): visible names are materialized
/// into the Vm's `scopes.top` (plain bindings, i.e. the enclosing block
/// scope shape); the verbatim statement takes its node from the parse cache
/// and is **synthesized onto the original statement's span** (twice over:
/// relative paths resolve against the original file — `import()`'s path
/// resolution anchors on `span.id()`; diagnostic sites point at the real
/// statement). The original code handles source dispatch/loading (including
/// pub `typst_eval::import`'s file-not-found/cycle detection/package
/// validation)/the three bare-name tiers/Items nesting and unresolved/all
/// warnings. The diff is read back: newly bound values are returned in
/// `expected` order (bare names/renames/item names are all statically
/// known).
pub fn eval_import(
    src: &str,
    span: Span,
    expected: &[&str],
    captured: &[(&'static str, Value)],
    engine: &mut Engine,
    context: Tracked<Context>,
) -> SourceResult<Vec<Value>> {
    use typst_eval::{Eval as _, Vm};

    let mut node = cached_body_node(src);
    node.synthesize(span);
    if std::env::var_os("TRUST_TRACE_IMPORT").is_some() {
        eprintln!(
            "[eval_import] src={src:?} span_file={:?} span={:?}",
            span.id().map(|id| id.vpath().get_with_slash().to_string()),
            span
        );
    }
    let expr = node
        .cast::<ast::Expr>()
        .expect("import statement parses to an expression");
    // Visible names = the enclosing scope (plain bindings; import writes
    // new names and never touches read-only marks).
    let mut top = Scope::new();
    for (name, value) in captured {
        top.bind((*name).into(), Binding::detached(value.clone()));
    }
    let mut scopes = Scopes::new(Some(engine.library));
    scopes.top = top;
    let before: std::collections::HashSet<EcoString> =
        scopes.top.iter().map(|(k, _)| k.clone()).collect();
    let engine2 = Engine {
        world: engine.world,
        library: engine.library,
        introspector: engine.introspector,
        traced: engine.traced,
        sink: TrackedMut::reborrow_mut(&mut engine.sink),
        route: Route::extend(engine.route.track()),
    };
    let mut vm = Vm::new(engine2, context, scopes, span);
    expr.eval(&mut vm)?;
    let mut out = Vec::with_capacity(expected.len());
    for name in expected {
        match vm.scopes.top.get(name) {
            Some(binding) if !before.contains(*name) => {
                out.push(binding.read().clone());
            }
            _ => {
                return Err(eco_vec![SourceDiagnostic::error(
                    span,
                    eco_format!("import diff is missing binding `{name}` (generator bug)"),
                )])
            }
        }
    }
    Ok(out)
}

/// Interprets an **include statement** (same glue; mirrors `Eval for
/// ast::ModuleInclude`): returns its content, with no bindings read back.
pub fn eval_include(
    src: &str,
    span: Span,
    captured: &[(&'static str, Value)],
    engine: &mut Engine,
    context: Tracked<Context>,
) -> SourceResult<Content> {
    use typst_eval::{Eval as _, Vm};

    let mut node = cached_body_node(src);
    node.synthesize(span);
    let expr = node
        .cast::<ast::Expr>()
        .expect("include statement parses to an expression");
    let mut top = Scope::new();
    for (name, value) in captured {
        top.bind((*name).into(), Binding::detached(value.clone()));
    }
    let mut scopes = Scopes::new(Some(engine.library));
    scopes.top = top;
    let engine2 = Engine {
        world: engine.world,
        library: engine.library,
        introspector: engine.introspector,
        traced: engine.traced,
        sink: TrackedMut::reborrow_mut(&mut engine.sink),
        route: Route::extend(engine.route.track()),
    };
    let mut vm = Vm::new(engine2, context, scopes, span);
    match expr.eval(&mut vm)? {
        Value::Content(content) => Ok(content),
        // Mirrors the original: include always evaluates to content; any
        // other shape is a generator-side bug.
        v => Err(eco_vec![SourceDiagnostic::error(
            span,
            eco_format!("include evaluated to non-content {}", v.ty()),
        )]),
    }
}

/// Interpreted evaluation with read-back (the escape hatch for `#let`
/// embedded in math): **drives the pub `Vm`/`Eval` directly** (mirroring
/// eval_closure's internal shape — build the Vm with the captured clone as
/// `scopes.top`; after evaluation new bindings land in top, and the
/// `Scopes` field is pub so it can be read back directly), with zero
/// synthesized typst source and zero export tuples — the snippet evaluates
/// verbatim, embedded lets bind into top per typst semantics, and we share
/// typst's own evaluation machinery. Returns (expression value, sequence of
/// bound values for the exported names).
pub fn eval_vm_exports(
    src: &str,
    exports: &[&str],
    captured: &[(&'static str, Value)],
    pending: &[(&'static str, bool)],
    engine: &mut Engine,
    context: Tracked<Context>,
) -> SourceResult<(Value, Vec<Value>)> {
    use typst_eval::{Eval as _, Vm};

    let node = cached_body_node(src);
    let expr = node
        .cast::<ast::Expr>()
        .expect("cached body node casts to an expression");
    let scope = captured_scope(captured, pending, engine);
    let mut scopes = Scopes::new(Some(engine.library));
    scopes.top = scope;
    // Same engine/route shape as eval_closure: all fields pub, constructed
    // by copy; the route shares its depth counter via track+extend (nested
    // guards stay continuous).
    let engine = Engine {
        world: engine.world,
        library: engine.library,
        introspector: engine.introspector,
        traced: engine.traced,
        sink: TrackedMut::reborrow_mut(&mut engine.sink),
        route: Route::extend(engine.route.track()),
    };
    let mut vm = Vm::new(engine, context, scopes, node.span());
    let value = expr.eval(&mut vm)?;
    let out = exports
        .iter()
        .map(|name| {
            vm.scopes
                .top
                .get(name)
                .map(|b| b.read().clone())
                .unwrap_or(Value::None)
        })
        .collect();
    Ok((value, out))
}
